/bin/bash -lc "cat > /tmp/modal-browser-check/check.mjs <<'EOF'
import {chromium} from 'playwright';
import assert from 'node:assert/strict';
const browser = await chromium.launch({headless: true, args: ['--no-sandbox']});
const page = await browser.newPage({viewport: {width: 1440, height: 1000}, deviceScaleFactor: 1});
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:5174');
const trigger = page.getByRole('button', {name: 'Открыть модальное окно'});
const dialog = page.getByRole('dialog');
await page.screenshot({path: '/tmp/modal-browser-check/desktop.png', fullPage: true});
await trigger.click();
await dialog.waitFor({state: 'visible'});
await page.waitForTimeout(250);
assert.equal(await page.evaluate(() => document.activeElement.textContent), 'Отменить');
await page.screenshot({path: '/tmp/modal-browser-check/dialog.png', fullPage: true});
await page.getByRole('button', {name: 'Отменить', exact: true}).click();
await dialog.waitFor({state: 'hidden'});
assert.equal(await trigger.evaluate(el => el === document.activeElement), true);
assert.equal(await page.getByText('Действие успешно подтверждено', {exact: true}).count(), 0);
await trigger.click();
await page.keyboard.press('Escape');
await dialog.waitFor({state: 'hidden'});
await trigger.click();
await page.waitForTimeout(200);
await page.mouse.click(12, 12);
await dialog.waitFor({state: 'hidden'});
await trigger.click();
await page.getByRole('button', {name: 'Подтвердить', exact: true}).click();
await dialog.waitFor({state: 'hidden'});
assert.equal(await page.getByText('Действие успешно подтверждено', {exact: true}).isVisible(), true);
assert.equal(await page.getByText('Действие подтверждено', {exact: true}).isVisible(), true);
await page.getByRole('button', {name: 'Закрыть уведомление'}).click();
await page.setViewportSize({width: 375, height: 812});
await page.screenshot({path: '/tmp/modal-browser-check/mobile.png', fullPage: true});
assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth), true);
await trigger.click();
await page.waitForTimeout(200);
await page.screenshot({path: '/tmp/modal-browser-check/mobile-dialog.png', fullPage: true});
assert.equal(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth), true);
const bounds = await dialog.boundingBox();
assert.ok(bounds.x >= 0 && bounds.x + bounds.width <= 375);
await page.setViewportSize({width: 320, height: 640});
const cancelBounds = await page.getByRole('button', {name: 'Отменить', exact: true}).boundingBox();
const applyBounds = await page.getByRole('button', {name: 'Подтвердить', exact: true}).boundingBox();
assert.ok(cancelBounds.x >= 0 && applyBounds.x + applyBounds.width <= 320);
assert.deepEqual(errors, []);
console.log('PASS: opening, initial focus, cancel, focus restoration, Escape, outside click, confirmation, notification, mobile layout (375px / 320px), and no browser errors.');
await browser.close();
EOF"

